# Minkowski Distance Function
def minkowski_distance(a, b, p):
    if len(a) != len(b):
        raise ValueError("Vectors must have the same length")

    distance = sum(abs(a[i] - b[i]) ** p for i in range(len(a)))
    return distance ** (1 / p)

# Sample vectors
