# initialize_centroids(data, k)
def initialize_centroids(data, k):
    np.random.seed(42)
    random_indices = np.random.choice(len(data), k, replace=False)
    centroids = data[random_indices]
    return centroids

# assign_clusters(data, centroids)
# Uses previously defined minkowski_distance(..., p=2)
def assign_clusters(data, centroids):
    cluster_labels = []
    for point in data:
        distances = []
        for centroid in centroids:
            distance = minkowski_distance(point, centroid, 2)
            distances.append(distance)
        cluster_labels.append(np.argmin(distances))
    return np.array(cluster_labels)

# update_centroids(data, cluster_labels, k)
def update_centroids(data, cluster_labels, k):
    centroids = []
    for cluster in range(k):
        cluster_points = data[cluster_labels == cluster]
        if len(cluster_points) > 0:
            centroid = np.mean(cluster_points, axis=0)
        else:
            centroid = data[np.random.randint(len(data))]
        centroids.append(centroid)
    return np.array(centroids)

# kmeans(data, k)
def kmeans(data, k, max_iterations=100):
    centroids = initialize_centroids(data, k)
    for _ in range(max_iterations):
        cluster_labels = assign_clusters(data, centroids)
        new_centroids = update_centroids(
            data,
            cluster_labels,
            k
        )
        if np.allclose(centroids, new_centroids):
            break
        centroids = new_centroids
    return cluster_labels, centroids

