# Unit test case for all the functions used in this lab
class TestLabFunctions(unittest.TestCase):
    # label_encoding()
    def test_label_encoding(self):
        column = pd.Series(['A', 'B', 'A', 'C'])
        encoded, mapping = label_encoding(column)
        self.assertEqual(len(encoded), 4)
        self.assertEqual(len(mapping), 3)
        self.assertEqual(encoded[0], encoded[2])

    # one_hot_encoding()
    def test_one_hot_encoding(self):
        column = pd.Series(['Red', 'Blue', 'Red'])
        encoded = one_hot_encoding(column)
        self.assertEqual(encoded.shape[0], 3)
        self.assertEqual(encoded.shape[1], 2)

    # minkowski_distance()
    def test_minkowski_distance(self):
        a = [1, 2, 4]
        b = [4, 5, 6]
        distance = minkowski_distance(a, b, 2)
        self.assertAlmostEqual(
            distance,
            4.69041575982343,
            places=5
        )

    def test_minkowski_distance_invalid(self):
        with self.assertRaises(ValueError):
            minkowski_distance([1, 2], [1, 2, 3], 2)

    # dot_product()
    def test_dot_product(self):
        vec1 = [2, 3, 4, 5]
        vec2 = [5, 6, 7, 8]
        self.assertEqual(
            dot_product(vec1, vec2),
            96
        )

    # euc_Norm()
    def test_euc_norm(self):
        vec = [3, 4]

        self.assertEqual(
            euc_Norm(vec),
            5.0
        )

    # calculate_mean()
    def test_calculate_mean(self):
        data = [1, 2, 3, 4, 5]

        self.assertEqual(
            calculate_mean(data),
            3.0
        )

    # calculate_variance()
    def test_calculate_variance(self):
        data = [1, 2, 3, 4, 5]

        self.assertEqual(
            calculate_variance(data),
            2.0
        )

    # calculate_standard_deviation()
    def test_calculate_standard_deviation(self):
        data = [1, 2, 3, 4, 5]

        self.assertAlmostEqual(
            calculate_standard_deviation(data),
            np.sqrt(2),
            places=5
        )

    # initialize_centroids()
    def test_initialize_centroids(self):
        data = np.array([
            [1, 1],
            [2, 2],
            [3, 3],
            [4, 4]
        ])

        centroids = initialize_centroids(data, 2)
        self.assertEqual(
            centroids.shape,
            (2, 2)
        )

    # assign_clusters()
    def test_assign_clusters(self):
        data = np.array([
            [1, 1],
            [2, 2],
            [8, 8]
        ])

        centroids = np.array([
            [1, 1],
            [8, 8]
        ])

        labels = assign_clusters(
            data,
            centroids
        )

        self.assertEqual(len(labels), 3)

    # update_centroids()
    def test_update_centroids(self):
        data = np.array([
            [1, 1],
            [2, 2],
            [8, 8],
            [9, 9]
        ])

        labels = np.array([
            0,
            0,
            1,
            1
        ])

        centroids = update_centroids(
            data,
            labels,
            2
        )

        self.assertEqual(
            centroids.shape,
            (2, 2)
        )

        self.assertTrue(
            np.allclose(
                centroids[0],
                [1.5, 1.5]
            )
        )

    # kmeans()
    def test_kmeans(self):
        data = np.array([
            [1, 1],
            [1.5, 2],
            [2, 1],
            [8, 8],
            [9, 8],
            [8, 9]
        ])

        labels, centroids = kmeans(
            data,
            2
        )

        self.assertEqual(
            len(labels),
            len(data)
        )

        self.assertEqual(
            centroids.shape,
            (2, 2)
        )


